import{_ as n,o as a,c as i,a5 as h}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"Media Campaign — lộ trình triển khai sau Media Package","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/campaign-delivery-plan.md","filePath":"feature/media-package-campaign/campaign-delivery-plan.md"}'),e={name:"feature/media-package-campaign/campaign-delivery-plan.md"};function c(r,t,o,d,g,l){return a(),i("div",null,[...t[0]||(t[0]=[h('<h1 id="media-campaign-—-lo-trinh-trien-khai-sau-media-package" tabindex="-1">Media Campaign — lộ trình triển khai sau Media Package <a class="header-anchor" href="#media-campaign-—-lo-trinh-trien-khai-sau-media-package" aria-label="Permalink to &quot;Media Campaign — lộ trình triển khai sau Media Package&quot;">​</a></h1><p>Theo dõi tiến độ theo <a href="./implementation-roadmap.html">lộ trình 6 giai đoạn</a>. File hiện tại giữ thiết kế kỹ thuật và các phương án cần BA quyết định.</p><p><strong>Giai đoạn 1 hoàn thành thiết kế 2026-10-08:</strong> <a href="./phase-1-design/spec.html">spec</a>, <a href="./phase-1-design/plan.html">data/API/editor contract</a>, <a href="./phase-1-design/task.html">checklist</a>, <a href="./phase-1-design/test.html">test matrix</a>. A1–A3 đã được người dùng xác nhận.</p><p>Ngày: 2026-10-08. BA mới nhất thay thế đề xuất nhiều đợt hợp tác trong một Workspace. Code/migration cho giai đoạn 2–5 đã có; trạng thái kiểm chứng mới nhất nằm trong <a href="./implementation-roadmap.html">roadmap</a>, checkpoint 2026-10-10.</p><h2 id="_1-ba-đa-xac-nhan" tabindex="-1">1. BA đã xác nhận <a class="header-anchor" href="#_1-ba-đa-xac-nhan" aria-label="Permalink to &quot;1. BA đã xác nhận&quot;">​</a></h2><ul><li>Một Workspace gắn với một Media Campaign. Trước khi Manager tạo thì có 0 Campaign; sau khi tạo có đúng 1, kể cả Campaign đã hoàn thành. Chiến dịch mới dùng Workspace mới.</li><li>Manager tạo Campaign từ WorkspaceMediaPackage đã được hai bên approved.</li><li>Owner có tính năng Nhân bản Workspace để chọn thông tin/tài nguyên từ Workspace cũ đưa sang Workspace mới, giảm công việc setup. DA-1255 đã chốt copy từng thành viên và tùy chọn timezone; tài nguyên chờ module riêng.</li><li>Không triển khai nhiều đợt Package/Campaign trong cùng Workspace. Đề xuất đàm phán đợt tiếp theo trong cùng Workspace được thay thế bằng chuẩn bị Workspace mới.</li><li>Task tiếp tục dùng MongoDB theo V2. Phải nối editor PostgreSQL hiện tại vào cùng Task identity/source of truth trước khi hoàn thiện Campaign → backlog.</li><li>Client góp ý; Manager sửa Campaign; cả hai duyệt lại phiên bản nội dung đã sửa.</li><li>Manager chủ động mark Campaign COMPLETED; còn Task dang dở thì bắt buộc ghi lý do, giữ nguyên trạng thái Task con. Không tự complete chỉ vì Task list rỗng/đã xong hết.</li><li>Thêm EVENT_PLAN và PRESS_RECOMMENDATION vào tasks chung, collection riêng lưu nội dung theo taskId. Không mở scope hậu cần, nhân sự, vận hành sự kiện hoặc booking.</li><li>Gói mới dùng tổng sản lượng cả gói, không monthly allowance trong đợt này. Ba offeringModel cũ không còn quyết định luồng mới; giữ đọc legacy/snapshot đã chốt và không tự quy đổi gói theo tháng khi thiếu thông tin.</li></ul><h2 id="_2-hien-trang-va-tac-đong" tabindex="-1">2. Hiện trạng và tác động <a class="header-anchor" href="#_2-hien-trang-va-tac-đong" aria-label="Permalink to &quot;2. Hiện trạng và tác động&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phần</th><th>Hiện trạng</th><th>Thay đổi cần làm</th></tr></thead><tbody><tr><td>WorkspaceMediaPackage</td><td>workspace_id UNIQUE; một selection mỗi Workspace</td><td>Giữ quan hệ hiện tại; bỏ kế hoạch mở nhiều đợt</td></tr><tr><td>Campaign</td><td>Prototype tạo nhiều draft/allocations cho một agreement</td><td>Giới hạn một Campaign/Workspace, sửa UI không còn tạo thêm</td></tr><tr><td>Campaign approval/deploy</td><td>Approve chưa khả dụng, chưa có deploy</td><td>Hoàn thiện DA-948</td></tr><tr><td>Task</td><td>V2 Mongo; editor dùng JPA Task và FK PostgreSQL</td><td>Mongo đã chốt; còn thiết kế tích hợp editor</td></tr><tr><td>Duplicate Workspace</td><td>Chưa được audit implementation</td><td>Task riêng thuộc Workspace; chốt danh mục copy rồi mới code</td></tr></tbody></table><p>Audit cả số Campaign theo agreement và theo Workspace trước khi thêm constraint. Không tự xóa/gộp/chuyển Campaign cũ để migration chạy được. previous_terms chỉ giữ bản liền trước, không phải full negotiation history.</p><h2 id="_3-thu-tu-trien-khai-va-jira" tabindex="-1">3. Thứ tự triển khai và Jira <a class="header-anchor" href="#_3-thu-tu-trien-khai-va-jira" aria-label="Permalink to &quot;3. Thứ tự triển khai và Jira&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mốc</th><th>FR / Jira</th><th>Kết quả</th></tr></thead><tbody><tr><td>M0</td><td>DA-942/944/945/946; prototype DA-947</td><td>Baseline đã commit; không khẳng định mọi AC của Jira đã xong</td></tr><tr><td>M1</td><td>FR 3.5.5 — DA-947 / E50-06</td><td>Một Campaign/Workspace; kế hoạch, work items, UI xem/sửa</td></tr><tr><td>M2</td><td>FR 3.5.6 — DA-948 / E50-07</td><td>Client góp ý, Manager sửa, duyệt hai bên theo phiên bản</td></tr><tr><td>M3</td><td>FR 3.5.6 — DA-948, phối hợp E51</td><td>Sinh Task Mongo an toàn và mở được trong editor; Manager hoàn thành Campaign</td></tr><tr><td>M4</td><td>Duplicate Workspace — DA-1255 / E16-13</td><td>Owner chọn từng thành viên và tùy chọn timezone để tạo Workspace mới; tài nguyên chưa có module</td></tr><tr><td>M5</td><td>DA-949/950 — E50-08/09</td><td>Danh bạ đối tác và theo dõi hợp tác</td></tr><tr><td>M6</td><td>DA-951 — FR 3.5.7–3.5.10</td><td>Content Request ngoài kế hoạch, giữ luồng riêng</td></tr></tbody></table><p>M4 có thể triển khai độc lập sau khi audit tạo Workspace hiện tại, không chặn M1/M2. Không dùng các mã DA-943–946 để ngầm bao gồm Duplicate Workspace. Tạo task có Epic/Sprint và mã thật trước khi code; chưa tự tạo task hoặc cập nhật Jira trong lần này. Campaign Addendum chưa có task; phải xem lại tính tương thích với một Campaign/Workspace trước khi thiết kế, không tự tạo thêm Campaign trong cùng Workspace dưới tên Addendum.</p><h2 id="_4-thiet-ke-du-kien" tabindex="-1">4. Thiết kế dự kiến <a class="header-anchor" href="#_4-thiet-ke-du-kien" aria-label="Permalink to &quot;4. Thiết kế dự kiến&quot;">​</a></h2><h3 id="m1-—-campaign-planning" tabindex="-1">M1 — Campaign planning <a class="header-anchor" href="#m1-—-campaign-planning" aria-label="Permalink to &quot;M1 — Campaign planning&quot;">​</a></h3><ul><li>Giữ UNIQUE workspace_media_packages.workspace_id. Thêm unique FK media_campaigns.workspace_media_package_id và kiểm tra truy cập Workspace để đảm bảo 1:1. Không cho đổi agreement hoặc chuyển Campaign sang Workspace khác nhằm lách constraint.</li><li>Concurrent create phải trả Campaign đã tồn tại hoặc conflict rõ ràng. UI chuyển sang Xem/Chỉnh sửa Campaign khi đã có một bản, không cho tạo thêm dù bản trước COMPLETED.</li><li>Giữ snapshot/version Package; thêm content_version, work_items JSONB và concurrency guard. Mỗi đầu việc có ID ổn định, deliverableId, tên, loại phù hợp và hạn thực hiện.</li><li>Dùng EVENT_PLAN/PRESS_RECOMMENDATION đã chốt cho Event/press, không ép thành POST. Phối hợp schema/adapter chuyên biệt với chủ E51; dữ liệu nội dung tham chiếu taskId.</li><li>Một sản phẩm bàn giao có thể cần nhiều Task. Không trừ sản lượng theo số Task máy móc.</li><li>UI danh sách Workspace dẫn đến Campaign duy nhất; phần chi tiết gồm phạm vi gói đã chốt, chiến lược, brand guideline, timeline, đầu việc và approval.</li><li>Giữ tương thích endpoint hiện tại khi bổ sung API workspace-scoped. Khóa record để chống cập nhật mất dữ liệu. Không tạo hai service logic cho hai kiểu route.</li><li>Luồng mới dùng quantityBasis=TOTAL; không chọn period. Xử lý tương thích legacy theo phase-1-design/plan.md, không tự nhân hoặc chuyển monthly snapshot.</li></ul><h3 id="m2-—-gop-y-va-duyet" tabindex="-1">M2 — góp ý và duyệt <a class="header-anchor" href="#m2-—-gop-y-va-duyet" aria-label="Permalink to &quot;M2 — góp ý và duyệt&quot;">​</a></h3><ul><li>Client gửi góp ý; Manager sửa draft. Mọi sửa nội dung tăng contentVersion và làm mất hiệu lực cả hai approval. Reject/góp ý không xóa lịch sử đã duyệt.</li><li>Approve phải kèm version; lưu actor/version/timestamp. Một actor không được đại diện cả Agency và Client để tự hoàn thành hai phía.</li><li>Sau khi cả hai approve, giữ nội dung bất biến theo BA hiện hành; tiến độ vận hành tách khỏi nội dung. Không áp maxChanges của Package vào Campaign khi chưa được yêu cầu.</li><li>Inbox hiện có gửi thông báo cho phía đối diện, link đúng Workspace/Campaign. So sánh bản cũ/mới cho Client khi duyệt lại.</li></ul><h3 id="m3-—-deploy-va-complete" tabindex="-1">M3 — deploy và complete <a class="header-anchor" href="#m3-—-deploy-va-complete" aria-label="Permalink to &quot;M3 — deploy và complete&quot;">​</a></h3><ul><li>Mongo là nguồn chính cho Task. Thống nhất ID và chỉnh lookup/editor integration; giữ dữ liệu editor đang có, không ghi hai bản Task độc lập ở Mongo và PostgreSQL.</li><li>Outbox/deployment record bền vững ở PostgreSQL; unique key (campaignId, campaignWorkItemId), insert-only upsert để retry không reset Task hiện hữu. Partial unique index không ảnh hưởng Task thủ công/Content Request thiếu campaignWorkItemId.</li><li>Chỉ chuyển IN_PROGRESS sau khi tất cả Task cần sinh đã được ghi bền vững. Lưu tiến trình/lỗi và phục hồi được sau restart hoặc mất kết nối.</li><li>Task mới ở BACKLOG, chưa assignee/QC. Nội dung Post/Livestream/Survey/Meet theo E51. Không init lại Atlas; chỉ migration có kiểm tra dữ liệu và index phù hợp.</li><li>Manager mark completed từ IN_PROGRESS; lưu actor/time/reason/Task summary và xử lý request lặp an toàn. Có unfinished Task thì reason bắt buộc; không đổi Task con.</li><li>Quyền chuẩn bị Workspace mới không tự xác nhận hạn mức hoặc điều kiện deploy đồng thời giữa các Workspace; audit quy tắc Workspace/subscription hiện tại.</li></ul><h3 id="m4-—-duplicate-workspace-đe-xuat-đe-ba-review" tabindex="-1">M4 — Duplicate Workspace (đề xuất để BA review) <a class="header-anchor" href="#m4-—-duplicate-workspace-đe-xuat-đe-ba-review" aria-label="Permalink to &quot;M4 — Duplicate Workspace (đề xuất để BA review)&quot;">​</a></h3><p>Owner chọn Workspace nguồn → chọn Nhân bản → nhập tên mới, kiểm tra Client/Manager và chọn nhóm dữ liệu → xem tóm tắt → tạo Workspace mới → chọn/duyệt Package mới → Manager lập Campaign mới.</p><table tabindex="0"><thead><tr><th>Nhóm dữ liệu</th><th>Đề xuất, chưa mặc định copy</th></tr></thead><tbody><tr><td>Brand, mô tả, guideline, cấu hình phù hợp</td><td>Cho chọn copy; giá trị mới độc lập với nguồn</td></tr><tr><td>Tài liệu thương hiệu, material, template, hashtag</td><td>Chọn danh mục; audit quyền và cơ chế lưu file trước</td></tr><tr><td>Client/Manager/thành viên</td><td>Owner chọn lại hoặc xác nhận người được giữ; kiểm tra trạng thái/quyền hiện tại</td></tr><tr><td>Package</td><td>Có thể gợi ý gói catalogue đã dùng; nếu copy terms thì phải là draft cần duyệt lại</td></tr><tr><td>Campaign, Task, approval, chat, lịch sử</td><td>Đề xuất không copy như công việc đang thực hiện; Workspace nguồn giữ lịch sử</td></tr><tr><td>Social account/token, lời mời, lịch đăng, job</td><td>Không tự chuyển kết nối/quyền/thực thi; chốt quy trình kết nối riêng nếu cần</td></tr></tbody></table><ul><li>Scope đầu tiên đề xuất chỉ trong cùng Agency; kiểm tra Owner có quyền đọc nguồn và tạo đích. Cross-Agency cần yêu cầu riêng, không suy ra từ quyền Owner.</li><li>Có sourceWorkspaceId để truy vết, nhưng không phụ thuộc vòng đời nguồn. FK hoặc liên kết phải tránh cascade xóa dữ liệu đã copy khi xóa Workspace nguồn.</li><li>Tài nguyên tham chiếu chung và file copy riêng có chi phí/quyền/xóa khác nhau; phải chốt. Không dùng bản sao metadata trỏ vào object sẽ bị xóa theo Workspace cũ.</li><li>Idempotency cho thao tác tạo; nếu copy nhiều tài nguyên dùng tiến trình/job có retry và hiển thị lỗi rõ ràng. Không báo hoàn thành khi chỉ copy được một phần.</li><li>Workspace mới giữ package gate hiện tại; thao tác trên đích không ảnh hưởng nguồn.</li><li>Trước code: audit Workspace create/template/member/material services, viết đủ spec → plan → task → test riêng và phối hợp người phụ trách Workspace.</li></ul><h2 id="_5-quyet-đinh-va-cau-hoi-con-mo" tabindex="-1">5. Quyết định và câu hỏi còn mở <a class="header-anchor" href="#_5-quyet-đinh-va-cau-hoi-con-mo" aria-label="Permalink to &quot;5. Quyết định và câu hỏi còn mở&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Trạng thái mới</th></tr></thead><tbody><tr><td>Q1</td><td>Cho chuẩn bị/duyệt sớm; nay ở Workspace mới. Điều kiện deploy riêng chưa chốt</td></tr><tr><td>Q2</td><td>Mongo V2; thiết kế editor soft refs/backfill/cutover ở phase-1-design/plan.md, còn thực hiện và kiểm chứng</td></tr><tr><td>Q3</td><td>Đã chốt EVENT_PLAN/PRESS_RECOMMENDATION + collection riêng; phối hợp ownership và schema form trước implementation</td></tr><tr><td>Q4</td><td>Đã chốt Client góp ý, Manager sửa, hai bên duyệt lại</td></tr><tr><td>Q5</td><td>Đề xuất nhiều đợt trong một Workspace bị thay thế bởi Duplicate Workspace cho Owner</td></tr><tr><td>Q6</td><td>Đã chốt tổng sản lượng cả gói; không theo tháng trong đợt này</td></tr><tr><td>Q7</td><td>Đã chốt Manager được complete còn Task dang dở nếu ghi lý do; giữ nguyên Task con</td></tr><tr><td>D1</td><td>Owner được copy nhóm tài nguyên/thành viên nào; default chọn gì?</td></tr><tr><td>D2</td><td>File dùng chung hay sao chép độc lập; xử lý sửa/xóa nguồn và quota ra sao?</td></tr><tr><td>D3</td><td>Package chỉ gợi ý catalogue hay cho sao chép terms thành draft mới?</td></tr></tbody></table><h2 id="_6-repo-commit-va-kiem-thu" tabindex="-1">6. Repo, commit và kiểm thử <a class="header-anchor" href="#_6-repo-commit-va-kiem-thu" aria-label="Permalink to &quot;6. Repo, commit và kiểm thử&quot;">​</a></h2><ul><li>Infrastructure: migration mới + init đồng bộ; SQL trong docs dùng docs tag theo yêu cầu. Không sửa migration cũ. Business/Web triển khai theo từng mốc đã chốt.</li><li>Web: paired vi/en keys, light/dark/mobile, lỗi/loading/empty/permission states. Gateway /api/v1/** đã forward Business; chỉ sửa khi có nhu cầu thật.</li><li>Commit DA-947 cho planning; DA-948 cho approve/deploy. Duplicate Workspace dùng mã Jira được cấp, không dùng placeholder hay đánh dấu task Done khi mới có tài liệu.</li><li>Test một Campaign/Workspace kể cả concurrent create, COMPLETED hoặc đổi ID.</li><li>Test approve phiên bản cũ, reset cả hai approval, permission và notification.</li><li>Test crash/retry deploy không sinh trùng/reset Task; Post mở trong editor dùng cùng ID.</li><li>Test duplicate theo allowlist, người không phải Owner, retry, copy lỗi một phần, thành viên inactive, xóa/sửa nguồn, không copy approval/token/job, và package gate đích.</li><li>Demo bằng account hiện có; không seed account mới. Không thay đổi DB trong lần cập nhật này.</li><li>Các test cho BA mới đều chưa chạy vì chưa có implementation.</li></ul><h2 id="nguon-va-lich-su" tabindex="-1">Nguồn và lịch sử <a class="header-anchor" href="#nguon-va-lich-su" aria-label="Permalink to &quot;Nguồn và lịch sử&quot;">​</a></h2><p><a href="./../../team_guide.html">Team guide</a> · <a href="./../../plan/brandhub-master-plan.html">Master-plan</a> · <a href="./../../ba/04-media-package-campaign.html">BA</a> · <a href="./3-5-5-create-media-campaign/spec.html">FR 3.5.5</a> · <a href="./3-5-6-approve-media-campaign/spec.html">FR 3.5.6</a>.</p><p>Bản kế hoạch nhiều đợt trong một Workspace đã được thay thế bởi quyết định BA mới nhất ngày 2026-10-08: một Workspace/một Campaign, Owner nhân bản Workspace cho chiến dịch mới.</p>',30)])])}const m=n(e,[["render",c]]);export{s as __pageData,m as default};
